css:
:root {
  --sand: #FBF6EF;
  --dark-sand: #F3EBE2;
  --shell: #EBE2D7;
  --dark-shell: #BDB1A4;
  --stone: #8D857A;
  --dark-stone: #63574A;
  --black-sand: #1C1714;
  --sangria: #9B5A44;
  --olive: #77742A;
  --indigo: #333880;
}
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--sand);
  color: var(--black-sand);
  font-family: var(--font-inter), sans-serif;
  font-size: 15px;
  line-height: 1.7;
}

/* ── HEADER ── */
header {
  background: var(--black-sand);
  padding: 18px 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.header-left {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.header-prepared {
  font-family: var(--font-inter), sans-serif;
  font-size: 10px;
  color: var(--dark-shell);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.6;
}
.hero-byline {
  font-family: var(--font-inter), sans-serif;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--stone);
  margin: 8px 0 0 0;
}
.footer-logo {
  height: 32px;
  width: auto;
  max-width: none;
  filter: invert(1) brightness(3);
  display: block;
  margin: 0 auto 24px;
  opacity: 0.7;
}
.site-logo {
  height: 38px;
  width: auto;
  max-width: none;
  filter: invert(1) brightness(2);
  display: block;
  overflow: visible;
}
.wordmark {
  font-family: var(--font-inter), sans-serif;
  font-weight: 600;
  font-size: 20px;
  letter-spacing: 0.2em;
  color: var(--sand);
  text-transform: uppercase;
  text-decoration: none;
}
.header-right {
  font-family: var(--font-inter), sans-serif;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--stone);
}

/* ── HERO ── */
.hero {
  background: linear-gradient(135deg, #F4D9D4 0%, #F6E7D6 55%, #F8EFE2 100%);
  padding: 96px 48px 64px;
  text-align: center;
  border-bottom: 1px solid var(--shell);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '東京';
  position: absolute;
  font-family: var(--font-inter), sans-serif;
  font-size: 280px;
  font-weight: 700;
  color: #ffffff;
  opacity: 0.35;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  pointer-events: none;
  letter-spacing: -0.04em;
}
.hero-eyebrow {
  font-family: var(--font-inter), sans-serif;
  font-weight: 700;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--sangria);
  margin-bottom: 16px;
  position: relative;
}
.hero h1 {
  font-family: var(--font-cormorant), Georgia, serif;
  font-weight: 300;
  font-size: 58px;
  line-height: 1.0;
  color: var(--black-sand);
  letter-spacing: -0.025em;
  margin-bottom: 20px;
  position: relative;
}
.hero-sub {
  font-family: var(--font-cormorant), serif;
  font-style: italic;
  font-size: 17px;
  color: var(--stone);
  max-width: 540px;
  margin: 0 auto 0;
  position: relative;
}
.map-link {
  font-size: 9px;
  color: var(--sangria);
  text-decoration: none;
  font-family: var(--font-inter), sans-serif;
  font-weight: 600;
  letter-spacing: 0.08em;
  margin-left: 8px;
  opacity: 0.8;
}
.map-link:hover { opacity: 1; text-decoration: underline; }

/* ── STICKY NAV ── */
.cat-nav {
  position: sticky;
  top: 56px;
  z-index: 200;
  background: var(--sand);
  border-bottom: 1px solid var(--shell);
  padding: 0 48px;
  display: flex;
  gap: 0;
  overflow-x: auto;
}
.cat-nav::-webkit-scrollbar { height: 2px; }
.cat-nav::-webkit-scrollbar-track { background: var(--shell); }
.cat-nav::-webkit-scrollbar-thumb { background: var(--dark-shell); }
.cat-tab {
  font-family: var(--font-inter), sans-serif;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--stone);
  padding: 18px 22px;
  text-decoration: none;
  border-bottom: 2px solid transparent;
  transition: all 0.2s;
  white-space: nowrap;
  display: block;
}
.cat-tab:hover { color: var(--black-sand); border-bottom-color: var(--shell); }
.cat-tab.omakase:hover, .cat-tab.omakase.active { color: var(--black-sand); border-bottom-color: var(--sangria); }
.cat-tab.kaiseki:hover, .cat-tab.kaiseki.active { color: var(--black-sand); border-bottom-color: var(--indigo); }
.cat-tab.wagyu:hover, .cat-tab.wagyu.active { color: var(--black-sand); border-bottom-color: #8B4513; }
.cat-tab.ramen:hover, .cat-tab.ramen.active { color: var(--black-sand); border-bottom-color: #E8722A; }
.cat-tab.casual:hover, .cat-tab.casual.active { color: var(--black-sand); border-bottom-color: var(--olive); }
.cat-tab.vegvegan:hover, .cat-tab.vegvegan.active { color: var(--black-sand); border-bottom-color: #2A6A3E; }
.cat-tab.vegfriendly:hover, .cat-tab.vegfriendly.active { color: var(--black-sand); border-bottom-color: #5D8A34; }
.sec-eyebrow.vegvegan { color: #2A6A3E; }
.sec-eyebrow.vegfriendly { color: #5D8A34; }

/* ── MAIN ── */
.main { max-width: 1160px; margin: 0 auto; padding: 64px 48px 0; }

/* ── SECTION HEADER ── */
.sec {
  scroll-margin-top: 120px;
  margin-bottom: 72px;
}
.sec-head {
  margin-bottom: 36px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--shell);
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
.sec-head-left {}
.sec-eyebrow {
  font-family: var(--font-inter), sans-serif;
  font-weight: 700;
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--sangria);
  margin-bottom: 6px;
}
.sec-eyebrow.kaiseki { color: var(--indigo); }
.sec-eyebrow.wagyu { color: #8B4513; }
.sec-eyebrow.ramen { color: #E8722A; }
.sec-eyebrow.casual { color: var(--olive); }
.sec-title {
  font-family: var(--font-cormorant), Georgia, serif;
  font-weight: 300;
  font-size: 42px;
  letter-spacing: -0.025em;
  color: var(--black-sand);
  line-height: 1.05;
}
.sec-desc {
  font-size: 14px;
  color: var(--stone);
  max-width: 520px;
  margin-top: 8px;
}
.sec-count {
  font-family: var(--font-inter), sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--dark-shell);
  white-space: nowrap;
}

/* ── LEGEND ── */
.legend {
  background: white;
  border: 1px solid var(--shell);
  padding: 16px 24px;
  margin-bottom: 28px;
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  border-radius: 2px;
}
.legend-label {
  font-family: var(--font-inter), sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--dark-shell);
}
.legend-items { display: flex; gap: 20px; flex-wrap: wrap; }
.li {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-inter), sans-serif;
  font-size: 11px;
  color: var(--stone);
}

/* ── RESTAURANT CARD ── */
.card {
  background: white;
  border: 1px solid var(--shell);
  border-radius: 2px;
  margin-bottom: 20px;
  overflow: hidden;
  transition: box-shadow 0.2s;
}
.card:hover { box-shadow: 0 4px 20px rgba(0,0,0,0.07); }

.card-top {
  padding: 26px 32px 20px;
  display: flex;
  gap: 20px;
  align-items: flex-start;
  border-bottom: 1px solid var(--dark-sand);
}
.card-rank {
  font-family: var(--font-cormorant), Georgia, serif;
  font-size: 32px;
  font-weight: 300;
  color: var(--shell);
  letter-spacing: -0.03em;
  line-height: 1;
  flex-shrink: 0;
  min-width: 44px;
  padding-top: 4px;
}
.card-info { flex: 1; min-width: 0; }
.card-name {
  font-family: var(--font-cormorant), Georgia, serif;
  font-weight: 400;
  font-size: 22px;
  color: var(--black-sand);
  letter-spacing: -0.01em;
  margin-bottom: 4px;
}
.card-loc {
  font-family: var(--font-inter), sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--dark-shell);
  margin-bottom: 8px;
}
.card-desc {
  font-size: 13.5px;
  color: var(--stone);
  line-height: 1.65;
}
.card-right {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.stars {
  font-size: 16px;
  letter-spacing: 3px;
  color: var(--sangria);
  line-height: 1;
}
.award-tags {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
}
.atag {
  font-family: var(--font-inter), sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 4px 9px;
  border-radius: 1px;
  white-space: nowrap;
}
.atag.michelin3 { background: #1a1a1a; color: #f5e6c8; }
.atag.michelin2 { background: #2a2a2a; color: #f5e6c8; }
.atag.michelin1 { background: #3d3d3d; color: #f5e6c8; }
.atag.bib { background: var(--dark-sand); color: var(--stone); border: 1px solid var(--shell); }
.atag.oad { background: var(--indigo); color: #fff; }
.atag.green { background: var(--olive); color: #fff; }
.atag.inst { background: var(--sangria); color: #fff; }
.atag.selected { background: var(--shell); color: var(--dark-stone); }

/* ── INFO GRID ── */
.card-body { padding: 18px 32px 20px 32px; }
.info-grid {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}
.info-item {
  border-left: 2px solid var(--dark-sand);
  padding-left: 10px;
}
.il {
  font-family: var(--font-inter), sans-serif;
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dark-shell);
  margin-bottom: 3px;
}
.iv {
  font-family: var(--font-inter), sans-serif;
  font-size: 12px;
  font-weight: 500;
  color: var(--black-sand);
  line-height: 1.3;
}
.iv.yes { color: var(--olive); }
.iv.no { color: var(--dark-shell); }
.iv.limited { color: var(--sangria); }
.iv.na { color: var(--dark-shell); font-style: italic; }
.iv.price { font-size: 13px; font-weight: 600; color: var(--black-sand); }

/* ── BOOKING ROW ── */
.booking-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  align-items: center;
  padding-top: 14px;
  border-top: 1px solid var(--dark-sand);
}
.bl {
  font-family: var(--font-inter), sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--dark-shell);
  margin-right: 4px;
}
.btn {
  font-family: var(--font-inter), sans-serif;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 7px 13px;
  border-radius: 1px;
  text-decoration: none;
  display: inline-block;
  transition: opacity 0.15s;
}
.btn:hover { opacity: 0.82; }
.btn.tableall { background: var(--black-sand); color: var(--sand); }
.btn.tabelog { background: var(--sangria); color: white; }
.btn.pocket { background: var(--indigo); color: white; }
.btn.omakase { background: var(--stone); color: white; }
.btn.omakaseje { background: var(--dark-stone); color: white; }
.btn.na-btn { background: var(--dark-sand); color: var(--dark-shell); cursor: default; pointer-events: none; }
.btn.concierge { background: var(--dark-stone); color: white; }

/* ── NOTICE BANNER ── */
.notice {
  background: var(--dark-sand);
  border: 1px solid var(--shell);
  border-left: 3px solid var(--sangria);
  padding: 12px 20px;
  font-size: 13px;
  color: var(--dark-stone);
  margin-bottom: 24px;
  border-radius: 2px;
}
.notice strong { font-family: var(--font-inter), sans-serif; font-size: 10px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--sangria); display: block; margin-bottom: 3px; }

/* ── FOOTER ── */
footer {
  background: var(--black-sand);
  color: var(--stone);
  padding: 48px;
  text-align: center;
}
footer .wordmark { display: block; margin-bottom: 12px; font-size: 18px; }
footer p { font-family: var(--font-inter), sans-serif; font-size: 11px; color: var(--dark-shell); margin-bottom: 4px; }

@media (max-width: 900px) {
  .info-grid { grid-template-columns: repeat(4, 1fr); } .booking-row .bl { flex-basis: 100%; margin-right: 0; margin-bottom: 10px; }
}
@media (max-width: 640px) {
  .hero h1 { font-size: 36px; }
  .sec-title { font-size: 30px; }
  .main { padding: 40px 20px; }
  header { padding: 18px 20px; }
  .info-grid { grid-template-columns: repeat(2, 1fr); }
  .card-top { flex-direction: column; }
  .card-right { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 10px; } .award-tags { flex-direction: row; flex-wrap: wrap; align-items: center; gap: 6px; }
}

.site-footer {
  background: var(--black-sand);
  padding: 40px 48px 32px;
}
.disclaimer-inline {
  max-width: 780px;
  margin: 20px auto 0;
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 20px;
}
.disclaimer-inline p {
  font-family: var(--font-inter), sans-serif;
  font-size: 10.5px;
  color: var(--dark-shell);
  line-height: 1.8;
  text-align: center;
  margin: 0;
  opacity: 1;
}
